\set ON_ERROR_STOP on
INSERT INTO agent_definitions (id, type, display_name, category, default_config, idle_timeout_seconds, is_active, created_at, updated_at)
SELECT gen_random_uuid(), 'brief-fidelity-auditor', 'Brief Fidelity Auditor', 'analyst', $BFA$
{"processing_mode": "orchestrator", "timeout_seconds": 300, "workflow": {"start_step": "ensure_site_record", "steps": {"ensure_site_record": {"action": "ensure_site_record", "config": {"store_brief_in_content_data": false}, "next_step": "load_brief_context", "output_field": "site_record"}, "load_brief_context": {"action": "query_database", "config": {"query": "SELECT\n  (SELECT LEFT(data::text, 4000) FROM site_specs WHERE site_id=s.id AND aspect='mission_brief' AND is_current=true) AS mission_brief,\n  (SELECT LEFT(data::text, 3000) FROM site_specs WHERE site_id=s.id AND aspect='design_intent' AND is_current=true) AS design_intent,\n  (SELECT LEFT(data::text, 2000) FROM site_specs WHERE site_id=s.id AND aspect='content_direction' AND is_current=true) AS content_direction,\n  (SELECT string_agg(pg.name || ' [' || COALESCE(pg.page_type,'?') || ', ' || pg.build_status || '] uses: ' || COALESCE(pg.comps,'(no components)'), E'\\n' ORDER BY pg.name)\n   FROM (SELECT p.name, p.page_type, p.build_status,\n                (SELECT string_agg(DISTINCT cc.function, ', ') FROM page_components pc JOIN content_components cc ON pc.component_id=cc.id WHERE pc.page_id=p.id) AS comps\n         FROM pages p WHERE p.site_id=s.id AND p.status='active') pg) AS pages_inventory,\n  (SELECT count(*) FROM page_components pc2 JOIN pages p2 ON pc2.page_id=p2.id WHERE p2.site_id=s.id AND pc2.rendered_html ~ '<img') AS components_with_images,\n  (SELECT count(*) FROM page_components pc3 JOIN pages p3 ON pc3.page_id=p3.id WHERE p3.site_id=s.id) AS total_components\nFROM sites s WHERE s.id = $1", "params": ["site_record.site_id"], "output_format": "object"}, "next_step": "run_fidelity_audit", "output_field": "brief_context"}, "run_fidelity_audit": {"action": "execute_llm_prompt", "config": {"prompt": "You are auditing whether a built website is FAITHFUL TO ITS OWN BRIEF. You are not judging general quality or taste \u2014 only the gap between what the site's brief and design intent PROMISED and what the built site actually contains. A promise kept must not be flagged; a promise broken must be, with the brief's own words as evidence.\n\n## The brief (mission_brief spec)\n{{.brief_context.mission_brief}}\n\n## The design intent (design_intent spec)\n{{.brief_context.design_intent}}\n\n## Content direction\n{{.brief_context.content_direction}}\n\n## What was actually built\nPages and the components each uses:\n{{.brief_context.pages_inventory}}\n\nComponents containing images: {{.brief_context.components_with_images}} of {{.brief_context.total_components}} total components.\n\n## How to audit\n1. Extract each CONCRETE promise from the brief/design intent: named component classes (carousels, hover effects, swipeable strips, charts/infographics), imagery expectations (density, style), layout expectations (variety across pages vs one template), register/style expectations.\n2. For each promise, check the built inventory: is a component of that class present on any page where the brief implies it? Is imagery density plausible against an \"image-rich\" promise? Do pages vary in their component mix, or repeat one template?\n3. Report ONLY broken or under-delivered promises, up to 8, most load-bearing first. Quote the brief's exact phrase in the description. If the inventory genuinely satisfies a promise, do not report it.\n4. Severity: high = a headline promise absent site-wide; medium = present but materially under-delivered; low = minor shortfall.\n\nRespond with ONLY a JSON array of UP TO 8 findings. Each finding MUST include ALL of these fields:\n{\"category\":\"brief_fidelity\",\"severity\":\"high|medium|low\",\"description\":\"the broken promise \u2014 MUST quote the brief phrase being graded, then state the gap\",\"current_value\":\"what the built site actually has (from the inventory above)\",\"suggestion\":\"the specific, mechanical change that would honour the promise (name the component/page)\",\"acceptance_test\":\"a concrete check a different agent could run to confirm the promise is now kept\",\"affected_component\":\"component class or section involved, if any\",\"page\":\"the page it applies to, or site-wide\",\"max_fix_attempts\":2}\n\nDo not invent inventory facts: every current_value must come from the inventory given above. If the brief text above is empty, return [].", "ai_service": {"model": "claude-sonnet-4-6", "provider": "anthropic", "max_tokens": 4000, "api_key_env_var": "ANTHROPIC_API_KEY"}, "input_fields": ["brief_context", "site_record"]}, "next_step": "write_findings", "output_field": "fidelity_audit"}, "write_findings": {"action": "write_audit_findings", "config": {"site_id": "site_record.site_id", "audit_source": "brief-fidelity-audit", "findings_field": "fidelity_audit.result"}, "next_step": "complete", "output_field": "findings_written"}, "complete": {"action": "complete_workflow", "config": {"output_fields": ["brief_context", "fidelity_audit", "findings_written"]}}}}}$BFA$::jsonb, 600, true, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM agent_definitions WHERE type='brief-fidelity-auditor' AND deleted_at IS NULL)
RETURNING type, display_name, is_active;
